PROGRAM motor_interlock
VAR
    Motor : BOOL;
    MotorLatch : BOOL;
    EmergencyStopTimer : TON;
END_VAR

// Update the latch state based on Start and Stop buttons
MotorLatch := NOT Stop AND Start;

// Check for emergency stop
IF EStop = FALSE THEN
    // Emergency stop is active, de-energize the motor
    Motor := FALSE;
    // Reset the emergency stop timer
    EmergencyStopTimer(IN := FALSE, PT := T#0s);
ELSE
    // Emergency stop is not active, check the motor latch state
    IF MotorLatch THEN
        Motor := TRUE;
    ELSE
        Motor := FALSE;
    END_IF;
END_IF;

// Ensure the motor cannot start if the emergency stop is active
Motor := Motor AND EStop;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Reset the pump timer if the level is within the safe range
IF Level > LowLimit AND Level < HighLimit THEN
    PumpTimer(IN := FALSE);
ELSE
    PumpTimer(IN := TRUE, PT := T#1s); // Safe delay to ensure stability
END_IF;

// Control the inlet pump based on the pump timer output
PumpIn := NOT PumpTimer.Q;

// Control the outlet valve based on the current level
ValveOut := Level >= HighLimit OR (NOT PumpIn AND Level > LowLimit);

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prevLevel : INT := 50; -- Initial value, can be any valid level
    hysteresisLow : INT := 10;
    hysteresisHigh : INT := 90;
    pumpTimer : TON;
END_VAR

-- Check for overflow condition first
IF Level >= hysteresisHigh THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= hysteresisLow THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := prevLevel < Level;
    ValveOut := prevLevel > Level;
END_IF;

-- Update previous level for next cycle
prevLevel := Level;

-- Implementing the safety condition
IF Level >= hysteresisHigh AND PumpIn THEN
    PumpIn := FALSE; -- Ensure pump does not run when level is at or above high limit
END_IF;

END_PROGRAM

