PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorATimer : TON;
    DoorBTimer : TON;
    DoorARequested : BOOL := FALSE;
    DoorBRequested : BOOL := FALSE;
END_VAR

DoorA := FALSE;
DoorB := FALSE;

IF OpenA_Cmd THEN
    IF NOT DoorB THEN
        DoorA := TRUE;
        DoorARequested := TRUE;
        DoorBRequested := FALSE;
        DoorBTimer(IN := FALSE);
    END_IF;
ELSIF OpenB_Cmd THEN
    IF NOT DoorA THEN
        DoorB := TRUE;
        DoorBRequested := TRUE;
        DoorARequested := FALSE;
        DoorATimer(IN := FALSE);
    END_IF;
END_IF;

IF DoorARequested AND DoorBRequested THEN
    DoorA := TRUE;
    DoorB := FALSE;
    DoorARequested := TRUE;
    DoorBRequested := FALSE;
    DoorBTimer(IN := FALSE);
END_IF;

IF DoorA THEN
    DoorATimer(IN := TRUE, PT := T#1s);
END_IF;

IF DoorB THEN
    DoorBTimer(IN := TRUE, PT := T#1s);
END_IF;

IF DoorATimer.Q THEN
    DoorA := FALSE;
    DoorARequested := FALSE;
END_IF;

IF DoorBTimer.Q THEN
    DoorB := FALSE;
    DoorBRequested := FALSE;
END_IF;
END_PROGRAM

