PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R : BOOL;
    EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    NS_Green, NS_Yellow, NS_AllRed, EW_Green, EW_Yellow, EW_AllRed : TON;
END_VAR

NS_Green(IN := State = 0 OR State = 3, PT := T#2s);
NS_Yellow(IN := State = 1 OR State = 4, PT := T#1s);
NS_AllRed(IN := State = 2 OR State = 5, PT := T#1s);

EW_Green(IN := State = 3 OR State = 0, PT := T#2s);
EW_Yellow(IN := State = 4 OR State = 1, PT := T#1s);
EW_AllRed(IN := State = 5 OR State = 2, PT := T#1s);

NS_G := NS_Green.Q AND NOT NS_Yellow.Q AND NOT NS_AllRed.Q;
NS_Y := NS_Yellow.Q AND NOT NS_Green.Q AND NOT NS_AllRed.Q;
NS_R := NS_AllRed.Q AND NOT NS_Green.Q AND NOT NS_Yellow.Q;

EW_G := EW_Green.Q AND NOT EW_Yellow.Q AND NOT EW_AllRed.Q;
EW_Y := EW_Yellow.Q AND NOT EW_Green.Q AND NOT EW_AllRed.Q;
EW_R := EW_AllRed.Q AND NOT EW_Green.Q AND NOT EW_Yellow.Q;

CASE State OF
    0:
        IF NS_Green.Q THEN
            State := 1;
        ELSIF NS_AllRed.Q THEN
            State := 2;
        END_IF;
    1:
        IF NS_Yellow.Q THEN
            State := 0;
        ELSIF NS_AllRed.Q THEN
            State := 2;
        END_IF;
    2:
        IF NS_AllRed.Q THEN
            State := 3;
        END_IF;
    3:
        IF EW_Green.Q THEN
            State := 4;
        ELSIF EW_AllRed.Q THEN
            State := 5;
        END_IF;
    4:
        IF EW_Yellow.Q THEN
            State := 3;
        ELSIF EW_AllRed.Q THEN
            State := 5;
        END_IF;
    5:
        IF EW_AllRed.Q THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

PROGRAM intersection
VAR
    State : INT := 0;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL := FALSE;
    TNS_G, TEW_G, TNS_Y, TEW_Y, TNS_R, TEW_R : TON;
END_VAR

TNS_G(IN := State = 0 OR State = 3, PT := T#2s);
TEW_G(IN := State = 3 OR State = 0, PT := T#2s);
TNS_Y(IN := State = 1 OR State = 4, PT := T#1s);
TEW_Y(IN := State = 4 OR State = 1, PT := T#1s);
TNS_R(IN := State = 2 OR State = 5, PT := T#1s);
TEW_R(IN := State = 5 OR State = 2, PT := T#1s);

CASE State OF
    0: 
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    1: 
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    2: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    3: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
    4: 
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    5: 
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
END_CASE;

IF TNS_G.Q THEN
    State := 1;
ELSIF TNS_Y.Q THEN
    State := 2;
ELSIF TNS_R.Q AND TEW_G.Q THEN
    State := 3;
ELSIF TEW_G.Q THEN
    State := 4;
ELSIF TNS_R.Q AND TEW_R.Q THEN
    State := 5;
END_IF;

END_PROGRAM

PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    T_NS_G, T_NS_Y, T_NS_R, T_EW_G, T_EW_Y, T_EW_R : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

// Initialize state
State := 0;

// Main loop
WHILE TRUE DO
    // Reset outputs
    NS_G := FALSE;
    NS_Y := FALSE;
    NS_R := FALSE;
    EW_G := FALSE;
    EW_Y := FALSE;
    EW_R := FALSE;

    // Set current state based on the value of State
    CASE State OF
        0: 
            NS_G := TRUE;
            T_NS_G(IN := TRUE, PT := PT_GREEN);
            if T_NS_G.Q THEN
                State := 1;
            END_IF;
        1: 
            NS_Y := TRUE;
            T_NS_Y(IN := TRUE, PT := PT_YELLOW);
            if T_NS_Y.Q THEN
                State := 2;
            END_IF;
        2: 
            NS_R := TRUE;
            EW_R := TRUE;
            T_NS_R(IN := TRUE, PT := PT_ALLRED);
            T_EW_R(IN := TRUE, PT := PT_ALLRED);
            if T_NS_R.Q AND T_EW_R.Q THEN
                State := 3;
            END_IF;
        3: 
            EW_G := TRUE;
            T_EW_G(IN := TRUE, PT := PT_GREEN);
            if T_EW_G.Q THEN
                State := 4;
            END_IF;
        4: 
            EW_Y := TRUE;
            T_EW_Y(IN := TRUE, PT := PT_YELLOW);
            if T_EW_Y.Q THEN
                State := 5;
            END_IF;
        5: 
            NS_R := TRUE;
            EW_R := TRUE;
            T_NS_R(IN := TRUE, PT := PT_ALLRED);
            T_EW_R(IN := TRUE, PT := PT_ALLRED);
            if T_NS_R.Q AND T_EW_R.Q THEN
                State := 0;
            END_IF;
    END_CASE;

    // Ensure that only one direction can have a green light
    IF NS_G OR NS_Y THEN
        EW_R := TRUE;
    END_IF;
    IF EW_G OR EW_Y THEN
        NS_R := TRUE;
    END_IF;

    // Delay for a short period to prevent rapid state changes
    WAIT(10ms);
END_WHILE

END_PROGRAM

PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    T_Green_NS, T_Green_EW, T_Yellow_NS, T_Yellow_EW, T_AllRed : TON;
END_VAR

T_Green_NS(IN := State = 0 OR State = 3, PT := T#2s);
T_Green_EW(IN := State = 3 OR State = 0, PT := T#2s);
T_Yellow_NS(IN := State = 1 OR State = 4, PT := T#1s);
