END_VAR

CASE State OF
    0: // At-bottom
        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallUp AND DoorClosed THEN
            State := 1;
            UpTimer(IN := TRUE, PT := T#5s);
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    1: // Moving-up
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF UpTimer.Q OR AtTop THEN
            MotorUp := FALSE;
            If AtTop THEN
                State := 2;
            ELSE
                State := 0;
            END_IF;
        ELSIF CallDown AND DoorClosed THEN
            State := 3;
            DownTimer(IN := TRUE, PT := T#5s);
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    2: // At-top
        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed THEN
            State := 3;
            DownTimer(IN := TRUE, PT := T#5s);
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF DownTimer.Q OR AtBottom THEN
            MotorDown := FALSE;
            If AtBottom THEN
                State := 0;
            ELSE
                State := 2;
            END_IF;
        ELSIF CallUp AND DoorClosed THEN
            State := 1;
            UpTimer(IN := TRUE, PT := T#5s);
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;
END_CASE;
END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR

VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR

VAR
    State : INT := 0;
    UpTimer : TON;
    DownTimer : TON;
END_VAR

CASE State OF
    0: // At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
            MotorUp := TRUE;
            MotorDown := FALSE;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    1: // Moving-up
        IF AtTop OR Not CallUp OR Not DoorClosed THEN
            State := 2;
            MotorUp := FALSE;
            MotorDown := FALSE;
        ELSE
            MotorUp := TRUE;
            MotorDown := FALSE;
        END_IF;

    2: // At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
            MotorUp := FALSE;
            MotorDown := TRUE;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    3: // Moving-down
        IF AtBottom OR Not CallDown OR Not DoorClosed THEN
            State := 0;
            MotorUp := FALSE;
            MotorDown := FALSE;
        ELSE
            MotorUp := FALSE;
            MotorDown := TRUE;
        END_IF;
END_CASE

// Safety checks
MotorUp := MotorUp AND DoorClosed;
MotorDown := MotorDown AND DoorClosed;
MotorUp := MotorUp AND NOT MotorDown;
MotorDown := MotorDown AND NOT MotorUp;
END_PROGRAM

