PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR_INTERNAL
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
    T : TON;
END_VAR
CONSTANT
    CAP : INT := 3;
END_CONSTANT

T(IN := EntrySensor AND NOT PrevEntry, PT := T#1ms);
PrevEntry := EntrySensor;

T(IN := ExitSensor AND NOT PrevExit, PT := T#1ms);
PrevExit := ExitSensor;

IF T.Q THEN
    IF EntrySensor THEN
        Count := MIN(Count + 1, CAP);
        FullSign := (Count = CAP);
        EntryBarrierOpen := (NOT FullSign AND EntryReq);
    ELSIF ExitSensor THEN
        Count := MAX(Count - 1, 0);
        FullSign := (Count = CAP);
        EntryBarrierOpen := (NOT FullSign AND EntryReq);
    END_IF;
END_IF;

FullSign := (Count = CAP);
EntryBarrierOpen := (NOT FullSign AND EntryReq);

END_PROGRAM

PROGRAM garage
VAR
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
    Capacity : CONST INT := 3;
    EntryTimer : TON;
END_VAR

EntryTimer(IN := EntryReq AND NOT FullSign, PT := T#1s);

IF EntrySensor THEN
    IF NOT PrevEntry THEN
        IF Count < Capacity THEN
            Count := Count + 1;
            IF Count = Capacity THEN
                FullSign := TRUE;
            END_IF;
        END_IF;
    END_IF;
    PrevEntry := TRUE;
ELSE
    PrevEntry := FALSE;
END_IF;

IF ExitSensor THEN
    IF NOT PrevExit THEN
        IF Count > 0 THEN
            Count := Count - 1;
            FullSign := FALSE;
        END_IF;
    END_IF;
    PrevExit := TRUE;
ELSE
    PrevExit := FALSE;
END_IF;

IF EntryReq AND NOT FullSign THEN
