        IF StopPB OR NOT EStop THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        END_IF;
END_CASE;

// Safety check: Ensure StarK and DeltaK are never energized simultaneously
IF StarK AND DeltaK THEN
    StarK := FALSE;
    DeltaK := FALSE;
END_IF;

