                IF Level >= 90 THEN
                    State := 2;
                END_IF;
                Pump := TRUE;
                Valve := FALSE;
            2: // Draining
                IF Level <= 10 THEN
                    State := 0;
                END_IF;
                Pump := FALSE;
                Valve := TRUE;
        END_CASE;
    END_IF;

    // Ensure safety conditions
    IF Pump AND Valve THEN
        Pump := FALSE;
        Valve := FALSE;
    END_IF;

    IF Level >= 90 THEN
        Pump := FALSE;
    END_IF;

    IF Level <= 10 THEN
        Valve := FALSE;
    END_IF;

    // Update last state for debugging or logging
    LastState := State;
END_WHILE

