    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND NOT EStop AND Level < HighLevel THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF Level >= HighLevel THEN
            State := 2;
        END_IF;
        IF EStop THEN
            State := 0;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= LowLevel THEN
            State := 0;
        END_IF;
        IF EStop THEN
            State := 0;
        END_IF;
END_CASE

// Safety checks
IF Pump AND Valve THEN
    State := 0; // Force Idle if both pump and valve are on
END_IF;
IF Level >= HighLevel AND Pump THEN
    State := 0; // Force Idle if pump is running at or above HIGH level
END_IF;
IF Level <= LowLevel AND Valve THEN
    State := 0; // Force Idle if valve is open at or below LOW level
END_IF;

END_PROGRAM

PROGRAM tank_cycle
