    LOW : INT := 10;
END_CONSTANT

// Safety conditions
ASSERT (NOT(Pump AND Valve));
ASSERT (Level <= HIGH);
ASSERT (Valve OR Level >= LOW);

// Main logic
CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND (Level < HIGH) THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF Level >= HIGH OR EStop THEN
            State := 2;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF Level <= LOW OR EStop THEN
            State := 0;
        END_IF;
END_CASE

