    LH_Released := TRUE;
ELSE
    LH_Released := FALSE;
END_IF;

IF NOT RH THEN
    RH_Released := TRUE;
ELSE
    RH_Released := FALSE;
END_IF;

// Arm the system when both buttons are released
IF LH_Released AND RH_Released THEN
    Armed := TRUE;
END_IF;

// Disarm the system when either button is pressed
IF LH OR RH THEN
    Armed := FALSE;
END_IF;

// Check if both buttons are pressed and the system is armed
IF LH AND RH AND Armed THEN
    Actuator := TRUE;
ELSE
    Actuator := FALSE;
END_IF;
END_PROGRAM

