    Actuator : BOOL;
END_VAR
VAR
    Armed : BOOL := FALSE;
    ButtonPressCount : INT := 0;
    LHPressed : BOOL := FALSE;
    RHPressed : BOOL := FALSE;
END_VAR
VAR_CONSTANT
    DEBOUNCE_TIME : TIME := T#200ms;
END_VAR

// Debounce logic for LH and RH buttons
TON debounce_LH(IN := LH, PT := DEBOUNCE_TIME);
TON debounce_RH(IN := RH, PT := DEBOUNCE_TIME);

IF debounce_LH.Q THEN
    LHPressed := TRUE;
ELSE
    LHPressed := FALSE;
END_IF;

IF debounce_RH.Q THEN
    RHPressed := TRUE;
ELSE
    RHPressed := FALSE;
END_IF;

// Count button presses
IF LHPressed AND NOT LH THEN
    ButtonPressCount := ButtonPressCount + 1;
END_IF;

IF RHPressed AND NOT RH THEN
    ButtonPressCount := ButtonPressCount + 1;
END_IF;

// Reset button press count when both buttons are released
IF NOT LH AND NOT RH THEN
    ButtonPressCount := 0;
END_IF;

// Update Armed state
IF ButtonPressCount = 2 THEN
    Armed := TRUE;
ELSIF ButtonPressCount = 1 THEN
    Armed := FALSE;
END_IF;

// Run actuator only if both buttons are pressed and control is armed
Actuator := LH AND RH AND Armed;
END_PROGRAM

