PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    Pump1Timer : TON;
    Pump2Timer : TON;
END_VAR

Pump1Timer(IN := NOT EStop AND Demand AND (Lead = 0), PT := T#0s);
Pump2Timer(IN := NOT EStop AND Demand AND (Lead = 1), PT := T#0s);

IF EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0;
    PrevDemand := FALSE;
ELSIF NOT Demand AND PrevDemand THEN
    Lead := 1 - Lead;
    PrevDemand := FALSE;
ELSIF Demand THEN
    PrevDemand := TRUE;
END_IF;

Pump1 := Pump1Timer.Q;
Pump2 := Pump2Timer.Q;
END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpsRunning : BOOL := FALSE;
END_VAR

PumpsRunning := Pump1 OR Pump2;

IF NOT EStop THEN
    // Emergency stop activates
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        // Demand started
        PumpsRunning := TRUE;
    END_IF;

    IF NOT Demand AND PrevDemand THEN
        // Demand ended
        Lead := 1 - Lead; // Toggle lead
    END_IF;

    CASE Lead OF
        0:
            Pump1 := Demand AND NOT PumpsRunning;
            Pump2 := FALSE;
        1:
            Pump1 := FALSE;
            Pump2 := Demand AND NOT PumpsRunning;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_CASE;
END_IF;

PrevDemand := Demand;
END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
