    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpTimer : TON;
END_VAR

PumpTimer(IN := NOT EStop AND Demand, PT := T#0s);

IF NOT EStop THEN
    IF Demand THEN
        PumpTimer(IN := TRUE, PT := T#0s);
        IF PumpTimer.Q THEN
            Pump1 := Lead = 0;
            Pump2 := Lead = 1;
            Lead := 1 - Lead;
        END_IF;
    ELSE
        IF NOT PrevDemand THEN
            Lead := 1 - Lead;
        END_IF;
    END_IF;
ELSE
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;

PrevDemand := Demand;
END_PROGRAM

