END_VAR

VAR_INTERNAL
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    TmpPump1 : BOOL := FALSE;
    TmpPump2 : BOOL := FALSE;
END_VAR

// Edge detection for Demand falling edge
PrevDemand := Demand;

IF NOT EStop THEN
    // Stop both pumps if EStop is active
    TmpPump1 := FALSE;
    TmpPump2 := FALSE;
ELSE
    IF NOT PrevDemand AND Demand THEN
        // Falling edge detected, switch lead
        Lead := 1 - Lead;
    END_IF;

    CASE Lead OF
        0:
            TmpPump1 := Demand;
            TmpPump2 := FALSE;
        1:
            TmpPump1 := FALSE;
            TmpPump2 := Demand;
    ELSE
        TmpPump1 := FALSE;
        TmpPump2 := FALSE;
    END_CASE;
END_IF;

// Assign output values
Pump1 := TmpPump1;
Pump2 := TmpPump2;

