PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    TmpPrevDemand : BOOL;
    LeadPump : BOOL;
END_VAR

TmpPrevDemand := PrevDemand;
PrevDemand := Demand;

LeadPump := NOT(EStop);

IF Demand AND LeadPump THEN
    Pump1 := (Lead = 0);
    Pump2 := (Lead = 1);
    IF NOT(TmpPrevDemand) AND Demand THEN
        Lead := NOT(Lead);
    END_IF;
ELSE
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;
END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR_INTERNAL
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    T1 : TON;
END_VAR

// Check for falling edge of Demand
PrevDemand := Demand;

IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        // Demand has started
        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
            Lead := 1;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
            Lead := 0;
        END_IF;
    ELSIF NOT Demand AND PrevDemand THEN
        // Demand has ended
        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
        END_IF;
    END_IF;
END_IF;

END_PROGRAM

