    PumpTimer : TON;
END_VAR

PumpTimer(IN := NOT(EStop), PT := T#0s);

PrevDemand := Demand;

IF NOT(EStop) THEN
    IF Demand AND NOT(PrevDemand) THEN
        Lead := 1 - Lead; // Toggle Lead on rising edge of Demand
    END_IF;

    CASE Lead OF
