    // Check for falling edge of demand to alternate lead
    IF NOT PrevDemand AND Demand THEN
        // Toggle the lead state on falling edge of demand
        Lead := 1 - Lead;
    END_IF;

    // Assign output based on lead state and demand
    CASE Lead OF
        0:
            Pump1 := Demand;
            Pump2 := FALSE;
        1:
            Pump1 := FALSE;
            Pump2 := Demand;
